theorem MeasureTheory.extracted_1.{u_4} {α : Type u_4} {x : MeasurableSpace α} {μ : Measure α} {s t : Set α}
  (h : μ t ≠ ⊤ := by finiteness) (hs : μ s < ⊤) : μ.real s ≤ μ.real (s ∪ t) := by
  exact measureReal_mono subset_union_left (measure_union_lt_top hs h.lt_top).ne

theorem MeasureTheory.extracted_1.{u_4} {α : Type u_4} {x : MeasurableSpace α} {μ : Measure α} {s t : Set α}
  (h : μ t ≠ ⊤ := by finiteness) (hs : μ s = ⊤) : μ.real s ≤ μ.real (s ∪ t) := by
  simp [Measure.real, hs]

